package com.bank.payment;

import java.util.HashMap;
import java.util.Map;

// Stand-in for Redis: maps an idempotency key to the stored payment result.
class IdempotencyStore {
    private final Map<String, String> store = new HashMap<>();

    boolean exists(String key) { return store.containsKey(key); }
    String get(String key) { return store.get(key); }
    void put(String key, String result) { store.put(key, result); }
}
