package com.bank.payment;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Transactional outbox: events recorded here are relayed to Kafka by a relay.
class EventOutbox {
    private static final Logger log = Logger.getLogger(EventOutbox.class.getName());
    private final List<String> events = new ArrayList<>();

    void record(String event) {
        events.add(event);
        log.info(() -> "Outbox recorded event: " + event);
    }

    // Simulates the relay publishing outbox rows to Kafka topic payment-events.
    void relayToKafka() {
        events.forEach(e -> log.info(() -> "Kafka[payment-events] <- " + e));
        events.clear();
    }
}
