package com.bank.payment;

import java.math.BigDecimal;
import java.util.logging.Level;
import java.util.logging.Logger;

// Idempotent payment with a Saga: debit → credit, compensate on failure.
class PaymentService {
    private static final Logger log = Logger.getLogger(PaymentService.class.getName());

    private final IdempotencyStore idempotency;
    private final EventOutbox outbox;
    private int paymentCounter = 0;

    PaymentService(IdempotencyStore idempotency, EventOutbox outbox) {
        this.idempotency = idempotency;
        this.outbox = outbox;
    }

    String transfer(String idempotencyKey, Account from, Account to, BigDecimal amount) {
        // Idempotency check: return the stored result for a repeated request.
        if (idempotency.exists(idempotencyKey)) {
            String cached = idempotency.get(idempotencyKey);
            log.info(() -> "Idempotent hit for key " + idempotencyKey + " -> " + cached);
            return cached;
        }

        // Saga step 1: debit sender (local transaction).
        from.debit(amount);
        log.info(() -> "Debited " + from.getAccountId() + " Rs." + amount);

        try {
            // Saga step 2: credit receiver (local transaction).
            to.credit(amount);
            log.info(() -> "Credited " + to.getAccountId() + " Rs." + amount);
        } catch (RuntimeException ex) {
            // Compensation: undo the debit so no money is lost.
            from.credit(amount);
            log.log(Level.SEVERE, "Credit failed — compensated debit for " + from.getAccountId(), ex);
            throw ex;
        }

        // Saga step 3 + outbox in the same logical transaction.
        String paymentId = "TXF-" + (++paymentCounter);
        String result = paymentId + ":COMPLETED";
        idempotency.put(idempotencyKey, result);
        outbox.record("PAYMENT " + from.getAccountId() + "->" + to.getAccountId()
                + " Rs." + amount + " " + result);
        return result;
    }
}
