package com.bank.payment;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class PaymentGatewayDemo {
    private static final Logger log = Logger.getLogger(PaymentGatewayDemo.class.getName());

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        IdempotencyStore idempotency = new IdempotencyStore();
        EventOutbox outbox = new EventOutbox();
        PaymentService service = new PaymentService(idempotency, outbox);

        BigDecimal rentAmount = new BigDecimal("50000");

        // 1. First transfer — succeeds.
        String r1 = service.transfer("IDEM-RENT-001", rajesh, priya, rentAmount);
        log.info(() -> "Transfer 1 result: " + r1);

        // 2. Retry with same idempotency key — no double charge.
        String r2 = service.transfer("IDEM-RENT-001", rajesh, priya, rentAmount);
        log.info(() -> "Transfer 2 (retry) result: " + r2);

        log.info(() -> "Rajesh balance: Rs." + rajesh.getBalance());
        log.info(() -> "Priya balance: Rs." + priya.getBalance());

        // Relay outbox events to Kafka for async consumers.
        outbox.relayToKafka();
    }
}
